    if (status == 529)
        return {"service_overloaded", "The " + name + " service is overloaded. Try again shortly.", true};
    // JusPrin Cloud answers 503 when the model provider is down or the server
    // is busy, and 504 when the provider took too long. Any other 5xx from it
    // is JusPrin's own fault; from a provider of the person's own key, any 5xx
    // is the provider's outage.
    if (status == 503 || (status >= 500 && !m_config.profile.account_sign_in))
        return {"service_unavailable", "The " + name + " service is temporarily unavailable.", true};
