    if (status == 408 || (status == 504 && m_config.profile.account_sign_in) || (status == 0 && timed_out))
        return {"timeout", "The AI request timed out.", true};
    // No status: the request never got an answer.
    if (status == 0)
        return {"network_error", "The AI request could not reach the " + name + " service.", true};
    // A status nobody planned for: the service answered, and refused.
    report_unexpected(unexpected_answer(status, body));
    return {"unexpected_error", "Something went wrong on our side, so the AI could not answer this message.", false};
}

