{
    namespace JP = Slic3r::GUI::JusPrin;
    std::vector<JP::UnexpectedError> reports;
    const JP::ReportSink previous = JP::set_report_sink([&reports](const JP::UnexpectedError& e) { reports.push_back(e); });
    const std::string body = R"({"type":"error","error":{"type":"invalid_request_error","message":"messages.1: bad"},"request_id":"req_1"})";
    std::vector<std::string> failures;
